from collections import deque

def topo_sort_kahn(n, graph):
    in_degree = [0] * n
    for node in range(n):
        for neighbor in graph[node]:
            in_degree[neighbor] += 1

    queue = deque(node for node in range(n) if in_degree[node] == 0)
    order = []
    while queue:
        node = queue.popleft()
        order.append(node)
        for neighbor in graph[node]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                queue.append(neighbor)

    return order if len(order) == n else None   # None signals a cycle
```

The final length check — `len(order) == n` — is not an afterthought, it's the cycle detector: any node stuck in a mutual dependency never reaches in-degree 0, so it's never added, and the output comes up short.

```python
def topo_sort_dfs(n, graph):
    visited = set()
    finish_stack = []

    def dfs(node):
        visited.add(node)
        for neighbor in graph[node]:
            if neighbor not in visited:
                dfs(neighbor)
        finish_stack.append(node)     # push on finish, not on entry

    for node in range(n):
        if node not in visited:
            dfs(node)

    return finish_stack[::-1]          # reverse: last-finished goes first
```

Note where `finish_stack.append(node)` sits — **after** the loop over neighbors, not before. Pushing on entry instead of on finish would record discovery order, not finish order, and produce a completely wrong result.
